settings.custom_liquid:
{% comment %} Contact Us - Custom Liquid Block {% endcomment %}
<div class="cus-section" id="cus-{{ section.id }}">
  <div class="cus-wrapper">
    <h2 class="cus-title">Contact Us:</h2>
    {% form 'contact', id: 'CusContactForm' %}
      <div class="cus-card">
        <div class="cus-row">
          <div class="cus-group">
            <label for="CusContactForm-first-name">First Name <span class="cus-required">*</span></label>
            <input type="text" id="CusContactForm-first-name" name="contact[first_name]" autocomplete="given-name" required>
          </div>
          <div class="cus-group">
            <label for="CusContactForm-last-name">Last Name <span class="cus-required">*</span></label>
            <input type="text" id="CusContactForm-last-name" name="contact[last_name]" autocomplete="family-name" required>
          </div>
        </div>
        <div class="cus-row">
          <div class="cus-group">
            <label for="CusContactForm-age">Age <span class="cus-required">*</span></label>
            <input type="number" id="CusContactForm-age" name="contact[age]" min="1" max="120" required>
          </div>
          <div class="cus-group">
            <label for="CusContactForm-job-title">Job Title <span class="cus-required">*</span></label>
            <input type="text" id="CusContactForm-job-title" name="contact[job_title]" autocomplete="organization-title" required>
          </div>
        </div>
        <div class="cus-row">
          <div class="cus-group">
            <label for="CusContactForm-phone">Phone Number <span class="cus-required">*</span></label>
            <input type="tel" id="CusContactForm-phone" name="contact[phone]" autocomplete="tel" required>
          </div>
          <div class="cus-group">
            <label for="CusContactForm-company">Company Name <span class="cus-required">*</span></label>
            <input type="text" id="CusContactForm-company" name="contact[company]" autocomplete="organization" required>
          </div>
        </div>
        <div class="cus-row">
          <div class="cus-group">
            <label for="CusContactForm-email">Email <span class="cus-required">*</span></label>
            <input type="email" id="CusContactForm-email" name="contact[email]" autocomplete="email" required>
          </div>
          <div class="cus-group">
            <label for="CusContactForm-country">Country <span class="cus-required">*</span></label>
            <input type="text" id="CusContactForm-country" name="contact[country]" autocomplete="country-name" required>
          </div>
        </div>
        <div class="cus-row">
          <div class="cus-group">
            <label for="CusContactForm-city">City <span class="cus-required">*</span></label>
            <input type="text" id="CusContactForm-city" name="contact[city]" autocomplete="address-level2" required>
          </div>
          <div class="cus-group">
            <label for="CusContactForm-industry">Industry <span class="cus-required">*</span></label>
            <input type="text" id="CusContactForm-industry" name="contact[industry]" required>
          </div>
        </div>
        <div class="cus-row">
          <div class="cus-group">
            <label for="CusContactForm-budget">Preliminary Budget <span class="cus-required">*</span></label>
            <input type="text" id="CusContactForm-budget" name="contact[preliminary_budget]" required>
          </div>
          <div class="cus-group">
            <label for="CusContactForm-items">Number of Items Needed <span class="cus-required">*</span></label>
            <input type="number" id="CusContactForm-items" name="contact[number_of_items]" min="1" required>
          </div>
        </div>
        <div class="cus-row">
          <div class="cus-group cus-group--full">
            <label for="CusContactForm-referral">How Did You Know About Us <span class="cus-required">*</span></label>
            <input type="text" id="CusContactForm-referral" name="contact[how_did_you_know]" required>
          </div>
        </div>
        <div class="cus-row">
          <div class="cus-group cus-group--full">
            <label for="CusContactForm-body">Your Request ( Be as specific as possible )<span class="cus-required">*</span></label>
            <textarea id="CusContactForm-body" name="contact[body]" rows="5" required></textarea>
          </div>
        </div>
      </div>
      <div class="cus-submit-wrapper">
        <button type="submit" id="cus-submit-btn" class="cus-submit-btn">Submit</button>
      </div>
    {% endform %}
  </div>
</div>
<style>
  .cus-section {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif;
    padding: 60px 20px;
    background-color: #ffffff;
  }
  .cus-wrapper {
    max-width: 760px;
    margin: 0 auto;
  }
  .cus-title {
    font-size: 2.8rem;
    font-weight: 800;
    text-align: center;
    color: #111111;
    margin: 0 0 32px 0;
    letter-spacing: -0.5px;
  }
  .cus-card {
    background-color: #f2f2f2;
    border-radius: 20px;
    padding: 36px 36px 28px 36px;
    margin-bottom: 32px;
  }
  .cus-row {
    display: flex;
    gap: 24px;
    margin-bottom: 24px;
  }
  .cus-group {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 8px;
  }
  .cus-group--full {
    flex: 1 1 100%;
    width: 100%;
  }
  .cus-group label {
    font-size: 1.4rem;
    font-weight: 500;
    color: #111111;
    margin: 0;
  }
  .cus-required {
    color: #cc0000;
  }
  .cus-group input[type="text"],
  .cus-group input[type="tel"],
  .cus-group input[type="email"],
  .cus-group input[type="number"] {
    background-color: #e0e0e0;
    border: none;
    border-radius: 10px;
    padding: 14px 16px;
    font-size: 1.4rem;
    color: #111111;
    width: 100%;
    box-sizing: border-box;
    outline: none;
    transition: background-color 0.2s ease, box-shadow 0.2s ease;
    -webkit-appearance: none;
    appearance: none;
  }
  .cus-group input[type="text"]:focus,
  .cus-group input[type="tel"]:focus,
  .cus-group input[type="email"]:focus,
  .cus-group input[type="number"]:focus {
    background-color: #d5d5d5;
    box-shadow: 0 0 0 2px rgba(0,0,0,0.15);
  }
  .cus-group textarea {
    background-color: #e0e0e0;
    border: none;
    border-radius: 10px;
    padding: 14px 16px;
    font-size: 1.4rem;
    color: #111111;
    width: 100%;
    box-sizing: border-box;
    outline: none;
    resize: vertical;
    min-height: 110px;
    font-family: inherit;
    transition: background-color 0.2s ease, box-shadow 0.2s ease;
    -webkit-appearance: none;
    appearance: none;
  }
  .cus-group textarea:focus {
    background-color: #d5d5d5;
    box-shadow: 0 0 0 2px rgba(0,0,0,0.15);
  }
  .cus-submit-wrapper {
    display: flex;
    justify-content: center;
  }
  .cus-submit-btn {
    background-color: #111111;
    color: #ffffff;
    border: none;
    border-radius: 10px;
    padding: 14px 52px;
    font-size: 1.4rem;
    font-weight: 600;
    cursor: pointer;
    letter-spacing: 0.3px;
    transition: background-color 0.2s ease, transform 0.1s ease;
    font-family: inherit;
  }
  .cus-submit-btn:hover {
    background-color: #333333;
  }
  .cus-submit-btn:active {
    transform: scale(0.98);
  }
  .cus-submit-btn:disabled {
    background-color: #888888;
    cursor: not-allowed;
  }
  @media (max-width: 600px) {
    .cus-title { font-size: 1.7rem; }
    .cus-card { padding: 24px 20px 20px 20px; }
    .cus-row { flex-direction: column; gap: 16px; }
    .cus-submit-btn { width: 60%; padding: 14px 20px; }
  }
</style>
<script>
  if (window.location.search.includes('contact_posted=true')) {
    window.location.replace('/pages/thank-you?status=success');
  }
</script>
